package bundler

import (
	"fmt"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/kratejs/krate/packages/compiler/ast"
	"github.com/kratejs/krate/packages/compiler/internal/diag"
	"github.com/kratejs/krate/packages/compiler/internal/inlineaction"
)

// hoistInlineActions rewrites the inline "use server" functions of a module
// (see package inlineaction) and returns the new source. The server action
// modules for them are generated by the build (build/inline_actions.go) from
// the same analysis, so the ids agree.
//
// An action that closes over nothing becomes an ordinary action reference and
// renders like an imported one. One that captures values needs an async server
// render, where each request seals the values. A capture in a component that
// is not async is reported through Bundle.SyncActionError, which the build
// raises only when the page is prerendered.
func (b *Bundler) hoistInlineActions(path, abs, src string) (string, bool) {
	if !inlineaction.Has(src) {
		return src, false
	}
	rel, err := filepath.Rel(b.root, abs)
	if err != nil {
		rel = abs
	}
	rel = filepath.ToSlash(rel)
	res, err := inlineaction.Hoist(src, inlineaction.Options{
		Path:   path,
		Rel:    rel,
		Dir:    filepath.Dir(abs),
		Client: HasUseClientDirective(src),
		TS:     b.tsOpts,
		Call: func(a *inlineaction.Action) string {
			if len(a.Captures) > 0 {
				return InlineActionCall(a)
			}
			if a.Name != "" {
				_ = b.noteActionImport(a.Name, actionURL(b.actionBasePath, a.ID))
				return fmt.Sprintf("__krateAction(%q)", a.ID)
			}
			// A function expression has no binding to register, so it becomes
			// the action's POST URL, which forms and form props resolve the
			// same way as an imported action.
			return strconv.Quote(actionURL(b.actionBasePath, a.ID))
		},
	})
	if err != nil {
		_ = b.setActionError(err)
		return src, false
	}
	if res == nil {
		return src, false
	}
	for _, a := range res.Actions {
		if len(a.Captures) == 0 || a.EnclosingAsync {
			continue
		}
		name := a.Name
		if name == "" {
			name = "this function"
		}
		b.syncActionErrs = append(b.syncActionErrs, diag.New(path, a.Pos.Line, a.Pos.Col,
			fmt.Sprintf("inline \"use server\" function %s captures %s, but the page is prerendered, so the value cannot be sealed per request", name, strings.Join(a.Captures, ", ")),
			"make the page render per request (an async page or layout, `export const dynamic = 'force-dynamic'`, or a revalidate), pass the value through a hidden form field, or move the function into a module whose first statement is \"use server\" and pass the values as arguments",
			lineOf(src, a.Pos.Line)).WithCode(diag.CodeInlineUseServer))
	}
	return res.Source, true
}

// InlineActionCall is the expression a capturing inline action is replaced
// with: __krateInlineAction(id, [captured values], [names], label).
func InlineActionCall(a *inlineaction.Action) string {
	return inlineaction.Call(a)
}

func lineOf(src string, line int) string {
	lines := strings.Split(src, "\n")
	if line < 1 || line > len(lines) {
		return ""
	}
	return strings.TrimRight(lines[line-1], "\r")
}

func isUseServerDirective(stmts []ast.Stmt) (ast.Pos, bool) {
	if len(stmts) == 0 {
		return ast.Pos{}, false
	}
	es, ok := stmts[0].(*ast.ExprStmt)
	if !ok {
		return ast.Pos{}, false
	}
	lit, ok := es.Expression.(*ast.Literal)
	if !ok || lit.Kind != ast.StringLit || strings.Trim(strings.TrimSpace(lit.Value), `"'`) != "use server" {
		return ast.Pos{}, false
	}
	pos := es.Position
	if pos.Line == 0 {
		pos = lit.Position
	}
	return pos, true
}

// FindInlineUseServer reports the position of the first inline "use server"
// directive (one inside a function body) in a parsed program.
func FindInlineUseServer(prog *ast.Program) (ast.Pos, bool) {
	return inlineaction.FirstPos(prog)
}
